class Solution {
public:
    int secondHighest(string s) {
        set<int> digits;
        for (char c : s)
            if (c >= '0' && c <= '9') digits.insert(c - '0');
        if (digits.size() < 2) return -1;
        auto it = digits.rbegin();
        return *(++it);
    }
};

